import random

def solve():
    n = 23
    # Try to build the graph
    for _ in range(1000):
        edges = set()
        degrees = [0] * n

        # Try to add edges
        # We want each vertex to have degree at least 4.
        # Let's try to add edges randomly and check for cycles.

        # To check for cycles of length 3, 4, 5:
        # We can use BFS to check the distance between u and v.
        # If we want to add edge (u, v), we must ensure there is no path of length 1, 2, 3, 4 between u and v.

        adj = [set() for _ in range(n)]

        def get_distance(u, v, max_dist):
            # BFS to find distance
            queue = [(u, 0)]
            visited = {u}
            while queue:
                curr, dist = queue.pop(0)
                if dist >= max_dist:
                    continue
                for neighbor in adj[curr]:
                    if neighbor == v:
                        return dist + 1
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append((neighbor, dist + 1))
            return float('inf')

        # Try to add edges until all degrees are at least 4
        possible_edges = []
        for i in range(n):
            for j in range(i + 1, n):
                possible_edges.append((i, j))
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if degrees[u] < 5 and degrees[v] < 5:
                # Check if adding (u, v) creates a cycle of length < 6
                # This means there must be no path of length 1, 2, 3, 4 between u and v
                if get_distance(u, v, 4) > 4:
                    adj[u].add(v)
                    adj[v].add(u)
                    degrees[u] += 1
                    degrees[v] += 1
                    edges.add((u, v))

        if all(d >= 4 for d in degrees):
            return list(edges)
    return None

result = solve()
print(result)
